"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([["507"],{6173(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/awesome-frames/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"link","href":"/awesome-frames/docs/eip-8141","label":"EIP-8141 primer","docId":"eip-8141","unlisted":false},{"type":"link","href":"/awesome-frames/docs/viem-frame-tx","label":"viem-frame-tx","docId":"viem-frame-tx","unlisted":false},{"type":"category","label":"Tools","items":[{"type":"link","href":"/awesome-frames/docs/tools/nostr-frame-account","label":"NostrFrameAccount","docId":"tools/nostr-frame-account","unlisted":false},{"type":"link","href":"/awesome-frames/docs/tools/lightning-rsa","label":"LightningRSA","docId":"tools/lightning-rsa","unlisted":false},{"type":"link","href":"/awesome-frames/docs/tools/ntrusign","label":"NTRUSign","docId":"tools/ntrusign","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/awesome-frames/docs/tools/"},{"type":"category","label":"Toys","items":[{"type":"link","href":"/awesome-frames/docs/toys/toy-curve-ecdh","label":"ToyCurveECDH","docId":"toys/toy-curve-ecdh","unlisted":false},{"type":"link","href":"/awesome-frames/docs/toys/stark-pedersen","label":"StarkPedersen","docId":"toys/stark-pedersen","unlisted":false},{"type":"category","label":"YoloRSA","items":[{"type":"link","href":"/awesome-frames/docs/toys/yolo-rsa-wide","label":"YoloRSA: wide tiers","docId":"toys/yolo-rsa-wide","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/awesome-frames/docs/toys/yolo-rsa"},{"type":"category","label":"Post-quantum survey","items":[{"type":"link","href":"/awesome-frames/docs/toys/post-quantum/ml-kem","label":"MlKem","docId":"toys/post-quantum/ml-kem","unlisted":false},{"type":"link","href":"/awesome-frames/docs/toys/post-quantum/lamport","label":"Lamport","docId":"toys/post-quantum/lamport","unlisted":false},{"type":"link","href":"/awesome-frames/docs/toys/post-quantum/falcon","label":"Falcon","docId":"toys/post-quantum/falcon","unlisted":false},{"type":"link","href":"/awesome-frames/docs/toys/post-quantum/ml-dsa","label":"ML-DSA","docId":"toys/post-quantum/ml-dsa","unlisted":false},{"type":"link","href":"/awesome-frames/docs/toys/post-quantum/mceliece","label":"Classic McEliece","docId":"toys/post-quantum/mceliece","unlisted":false},{"type":"link","href":"/awesome-frames/docs/toys/post-quantum/isogeny","label":"Isogeny-based (docs only)","docId":"toys/post-quantum/isogeny","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/awesome-frames/docs/toys/post-quantum/"}],"collapsed":true,"collapsible":true,"href":"/awesome-frames/docs/toys/"}]},"docs":{"eip-8141":{"id":"eip-8141","title":"EIP-8141 primer","description":"EIP-8141 introduces a new transaction type (0x06) built from a list of frames \u2014 contract calls tagged with a mode:","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"Introduction","description":"A developer playground for crafting EIP-8141 Frame transactions on Ethereum and running them against the only public Frame-tx-capable testnet that exists today \u2014 Hardhat v3 + rocketh for contracts, plus a standalone viem-based encoder package.","sidebar":"docsSidebar"},"tools/index":{"id":"tools/index","title":"Tools","description":"contracts/src/tools/ holds accounts meant to actually be deployed and used to authorize a Frame transaction \u2014 real, working, deployable. A tool is: a VERIFY-frame target contract, a signature scheme, and a script proving the round trip against a live (or simulated) Frame-tx-capable network. Deployability is the bar here, not cryptographic soundness \u2014 NostrFrameAccount and LightningRSA are genuinely sound; NTRUSign is deliberately weak, on purpose, and belongs here too because it\'s real and deployable, not because it\'s safe.","sidebar":"docsSidebar"},"tools/lightning-rsa":{"id":"tools/lightning-rsa","title":"LightningRSA","description":"A self-verifying EIP-8141 account authorized by a real RSASSA-PKCS1-v1_5/SHA-256 signature (RFC 8017 \xa79.2/\xa78.2) \u2014 unlike YoloRSA (deliberately tiny, deliberately unpadded), this is meant to be sound at any modulus width an operator actually deploys with. Default target: RSA-2048.","sidebar":"docsSidebar"},"tools/nostr-frame-account":{"id":"tools/nostr-frame-account","title":"NostrFrameAccount","description":"A minimal, self-verifying Frame account authorized by a BIP-340/Nostr Schnorr signature instead of ECDSA \u2014 the same secp256k1 keypair that signs a Nostr event can authorize a Frame transaction directly, no key derivation in between.","sidebar":"docsSidebar"},"tools/ntrusign":{"id":"tools/ntrusign","title":"NTRUSign","description":"A self-verifying EIP-8141 account authorized by an NTRUSign signature \u2014 the predecessor to Falcon, and a real, historically broken lattice signature scheme unlike a toy that\'s never meant to be used, this account is real and deployable, exactly the point of this repo\'s weak-crypto-marketplace pivot \u2014 Frame transactions make it cheap to deploy cryptography that\'s weak on purpose and stake correspondingly little on it.","sidebar":"docsSidebar"},"toys/index":{"id":"toys/index","title":"Toys","description":"contracts/src/toys/ is illustrative \u2014 not meant to be deployed and used, unlike Tools. Classic and modern asymmetric primitives, implemented directly in raw Yul (and, in the post-quantum survey, plain TypeScript), as legibly as the language allows: real math, shrunk or chosen small enough to verify by hand or in a fresh keypair.","sidebar":"docsSidebar"},"toys/post-quantum/falcon":{"id":"toys/post-quantum/falcon","title":"Falcon","description":"Falcon-512, but only the verification half. Where MlKem got a full build and Lamport got a full build, Falcon stops at verification, for a real, specific reason: signing needs floating-point Gaussian sampling over the NTRU lattice (the \\"Falcon tree\\" FFT sampler) \u2014 a well-documented, genuinely hard-to-get-right-and-constant-time hazard, and part of why NIST\'s own FIPS 206 status updates cite it as the main reason Falcon\'s standardization took longer than ML-KEM\'s or ML-DSA\'s. FIPS 206 is still a Draft as of this writing (NIST\'s Initial Public Draft, August 2025; final expected late 2026/2027) \u2014 not a stable target to derive against yet.","sidebar":"docsSidebar"},"toys/post-quantum/index":{"id":"toys/post-quantum/index","title":"Post-quantum survey","description":"Prompted by a Vitalik Buterin post surveying post-quantum cryptography families \u2014 Falcon, ML-DSA, \\"some other lattice-based thing,\\" something code-based or isogeny-based, \\"even more esoteric.\\" Three scoping decisions shaped this pass, all deliberate:","sidebar":"docsSidebar"},"toys/post-quantum/isogeny":{"id":"toys/post-quantum/isogeny","title":"Isogeny-based (docs only)","description":"No code this pass \u2014 the one family in this survey scoped as prose-only from the start, and confirmed as the right call once the tractability was actually assessed. Real toy isogeny code needs V\xe9lu\'s-formula isogeny computation over extension fields, and \u2014 for reproducing anything shaped like the actual 2022 SIDH break \u2014 genus-2 Jacobian arithmetic via theta functions. That\'s a research-grade reimplementation, not a survey-pass item; the original attack code is SageMath specifically because it leans on finite-field-extension and genus-2 curve tooling that doesn\'t exist in plain JS/bigint.","sidebar":"docsSidebar"},"toys/post-quantum/lamport":{"id":"toys/post-quantum/lamport","title":"Lamport","description":"Hash-based, not lattice/code/isogeny-based like the rest of this survey. Filed under Vitalik\'s \\"even more esoteric\\" bucket, which is a little ironic on inspection: hash-based signatures are the most conservative PQC family there is \u2014 security reduces entirely to the preimage resistance of a hash function, no number-theoretic or algebraic hardness assumption at all. \\"Esoteric\\" here means \\"structurally foreign to this repo\'s algebraic mainstream\\" (ToyCurveECDH/YoloRSA/LightningRSA/MlKem all lean on some ring or curve), not \\"obscure or fragile\\" \u2014 if anything, this is the one entry in the whole survey nobody seriously doubts the security model of.","sidebar":"docsSidebar"},"toys/post-quantum/mceliece":{"id":"toys/post-quantum/mceliece","title":"Classic McEliece","description":"Code-based, not lattice/isogeny-based \u2014 a genuinely different hard problem a scrambled generator matrix G\' = S\xb7G\xb7P hides the real code\'s error-correcting structure from anyone without the secret S, P, and decoder.","sidebar":"docsSidebar"},"toys/post-quantum/ml-dsa":{"id":"toys/post-quantum/ml-dsa","title":"ML-DSA","description":"Real parameters, no working sign() or verify(). This page \u2014 and the file it documents \u2014 exist to record why on purpose, rather than ship a half-working implementation. \\"No half-finished implementations\\" is a rule this whole codebase follows; this is what following it looks like when a scheme turns out to be bigger than its survey slot.","sidebar":"docsSidebar"},"toys/post-quantum/ml-kem":{"id":"toys/post-quantum/ml-kem","title":"MlKem","description":"A real, full-size key-encapsulation mechanism \u2014 not a shrunk toy. Where ToyCurveECDH/YoloRSA earn their pedagogy by shrinking a real scheme down to hand-verifiable size, that move doesn\'t work here every function is commented with its exact FIPS 203 algorithm number, derived directly from the primary standard (NIST.FIPS.203, csrc.nist.gov) \u2014 not from memory, not from reading an existing implementation\'s source.","sidebar":"docsSidebar"},"toys/stark-pedersen":{"id":"toys/stark-pedersen","title":"StarkPedersen","description":"Starknet\'s actual Pedersen hash function \u2014 the one StarkWare\'s own spec defines, the one @scure/starknet implements, the one a local Cairo project (ScarabSign) names as the reason its peer-to-peer bid-signature aggregation works at all \u2014 implemented directly in Yul, callable from any Ethereum contract. Unlike ToyCurveECDH, every number in this file is a real Starknet constant, not shrunk for legibility: the curve, the field, and the five \\"nothing up my sleeve\\" generator points are exactly what a Starknet node uses.","sidebar":"docsSidebar"},"toys/toy-curve-ecdh":{"id":"toys/toy-curve-ecdh","title":"ToyCurveECDH","description":"Elliptic-curve Diffie-Hellman over y\xb2 = x\xb3 + 2x + 2 (mod 17) \u2014 the textbook toy curve from Hankerson/Menezes/Vanstone\'s Guide to Elliptic Curve Cryptography. Its group has prime order 19 \u2014 small enough to enumerate and print on one page, which is the entire point: the same chord-and-tangent geometry that powers this repo\'s real secp256k1/BIP-340 work (BIP340.sol, NostrFrameAccount.yul), shrunk down until a curious reader can verify it by hand, and small enough that recovering a private scalar from its public point is a nineteen-iteration for loop, not a research problem.","sidebar":"docsSidebar"},"toys/yolo-rsa":{"id":"toys/yolo-rsa","title":"YoloRSA","description":"A ladder of deliberately-weak textbook RSA \\"wallets,\\" each sized to a specific real-world cracking difficulty \u2014 from mental arithmetic up to \\"needs a real factoring tool.\\" The idea: deploy one, fund it with testnet ETH, publish nothing but its public key (baked directly into the contract\'s own bytecode), and see how long a stranger takes to factor the modulus, recover the private exponent, forge a signature, and drain it.","sidebar":"docsSidebar"},"toys/yolo-rsa-wide":{"id":"toys/yolo-rsa-wide","title":"YoloRSA: wide tiers","description":"The wide-modulus sibling of YoloRSA: moduli spanning two EVM words (up to 512 bits) instead of one, sized against a real GNFS-based cost model rather than \\"small enough for a naive script.\\"","sidebar":"docsSidebar"},"viem-frame-tx":{"id":"viem-frame-tx","title":"viem-frame-tx","description":"npm","sidebar":"docsSidebar"}}}}')}}]);